-- مركز إنماء برو: two laptops, one centre (docs/sync/DECISION.md; DESIGN.md section 20).
--
-- GENERATED by scripts/generate-db-types.mjs from prisma/schema.prisma (the models,
-- rebuilds and capture LATER_MIGRATIONS gives this file in scripts/db/schema-tools.mjs)
-- and prisma/triggers.sql. Do not edit: change the sources and run `npm run db:types`.
-- Once an installer carries it, its text never changes again.
--
-- An installed copy applies it at its next start, in one transaction. Until sync is
-- set up, capture is off (SyncSession.capturing 0) and the program behaves as 1.0.0.

-- ── 1. The sync tables: six of this laptop's own, three shared ─────────────────

CREATE TABLE "SyncSession" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "capturing" INTEGER NOT NULL DEFAULT 0,
  "applying" INTEGER NOT NULL DEFAULT 0,
  "txId" TEXT,
  "hlc" TEXT,
  CHECK ("id" = 'session'),
  CHECK ("capturing" IN (0, 1) AND "applying" IN (0, 1))
) STRICT;

CREATE TABLE "SyncOutbox" (
  "seq" INTEGER PRIMARY KEY NOT NULL,
  "txId" TEXT NOT NULL,
  "hlc" TEXT NOT NULL,
  "tbl" TEXT NOT NULL,
  "rowId" TEXT NOT NULL,
  "op" TEXT NOT NULL,
  "data" TEXT NOT NULL,
  CHECK ("op" IN ('I', 'U', 'D'))
) STRICT;
CREATE INDEX "SyncOutbox_txId_idx" ON "SyncOutbox" ("txId");

CREATE TABLE "SyncCell" (
  "tbl" TEXT NOT NULL,
  "rowId" TEXT NOT NULL,
  "col" TEXT NOT NULL,
  "hlc" TEXT NOT NULL,
  PRIMARY KEY ("tbl", "rowId", "col")
) STRICT;

CREATE TABLE "SyncState" (
  "key" TEXT PRIMARY KEY NOT NULL,
  "value" TEXT NOT NULL
) STRICT;

CREATE TABLE "SyncHeld" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "originDeviceId" TEXT NOT NULL,
  "txSeq" INTEGER NOT NULL,
  "hlc" TEXT NOT NULL,
  "tbl" TEXT NOT NULL,
  "rowId" TEXT NOT NULL,
  "change" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "firstAt" TEXT NOT NULL,
  "lastTriedAt" TEXT NOT NULL,
  "tries" INTEGER NOT NULL DEFAULT 0,
  "resolvedAt" TEXT,
  "resolution" TEXT
) STRICT;
CREATE INDEX "SyncHeld_resolvedAt_idx" ON "SyncHeld" ("resolvedAt");
CREATE INDEX "SyncHeld_originDeviceId_txSeq_idx" ON "SyncHeld" ("originDeviceId", "txSeq");
CREATE INDEX "SyncHeld_tbl_rowId_idx" ON "SyncHeld" ("tbl", "rowId");

CREATE TABLE "SyncConflict" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "tbl" TEXT NOT NULL,
  "rowId" TEXT NOT NULL,
  "col" TEXT NOT NULL,
  "keptValue" TEXT NOT NULL,
  "keptHlc" TEXT NOT NULL,
  "otherValue" TEXT NOT NULL,
  "otherHlc" TEXT NOT NULL,
  "otherDeviceId" TEXT NOT NULL,
  "detectedAt" TEXT NOT NULL,
  "resolvedAt" TEXT,
  "resolution" TEXT
) STRICT;
CREATE INDEX "SyncConflict_resolvedAt_idx" ON "SyncConflict" ("resolvedAt");
CREATE INDEX "SyncConflict_tbl_rowId_idx" ON "SyncConflict" ("tbl", "rowId");

CREATE TABLE "SyncDevice" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "name" TEXT NOT NULL,
  "slot" INTEGER NOT NULL,
  "joinedAt" TEXT NOT NULL,
  "removedAt" TEXT,
  "removedReason" TEXT,
  "replacesDeviceId" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  FOREIGN KEY ("replacesDeviceId") REFERENCES "SyncDevice" ("id") ON DELETE RESTRICT,
  CHECK ("slot" IN (0, 1)),
  CHECK ("removedAt" IS NULL OR "removedReason" IS NOT NULL)
) STRICT;
CREATE UNIQUE INDEX "SyncDevice_active_slot" ON "SyncDevice" ("slot") WHERE "removedAt" IS NULL;

CREATE TABLE "SyncBooks" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "holderDeviceId" TEXT NOT NULL,
  "epoch" INTEGER NOT NULL,
  "handedAt" TEXT,
  "requestedByDeviceId" TEXT,
  "requestedAt" TEXT,
  "lastInvoiceNumber" TEXT,
  "lastReceiptNumber" TEXT,
  "forced" INTEGER NOT NULL DEFAULT 0,
  "reason" TEXT,
  "updatedAt" TEXT NOT NULL,
  FOREIGN KEY ("holderDeviceId") REFERENCES "SyncDevice" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("requestedByDeviceId") REFERENCES "SyncDevice" ("id") ON DELETE RESTRICT,
  CHECK ("id" = 'books'),
  CHECK ("forced" IN (0, 1)),
  CHECK ("forced" = 0 OR "reason" IS NOT NULL)
) STRICT;

CREATE TABLE "NumberBlock" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "key" TEXT NOT NULL,
  "year" INTEGER NOT NULL,
  "blockIndex" INTEGER NOT NULL,
  "size" INTEGER NOT NULL,
  "deviceId" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "answer" TEXT,
  "answeredAt" TEXT,
  "used" INTEGER NOT NULL DEFAULT 0,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  FOREIGN KEY ("deviceId") REFERENCES "SyncDevice" ("id") ON DELETE RESTRICT,
  CHECK ("kind" IN ('START', 'CLAIM', 'FALLBACK')),
  CHECK ("answer" IS NULL OR "answer" IN ('ACCEPTED', 'REFUSED')),
  CHECK ("size" > 0 AND "used" >= 0 AND "used" <= "size" AND "blockIndex" >= 0)
) STRICT;
CREATE INDEX "NumberBlock_key_year_blockIndex_idx" ON "NumberBlock" ("key", "year", "blockIndex");

CREATE TRIGGER "SyncSession_no_delete" BEFORE DELETE ON "SyncSession"
BEGIN SELECT RAISE(ABORT, 'NO_DELETE:SyncSession'); END;

CREATE TRIGGER "SyncDevice_no_delete" BEFORE DELETE ON "SyncDevice"
BEGIN SELECT RAISE(ABORT, 'NO_DELETE:SyncDevice'); END;

CREATE TRIGGER "SyncBooks_no_delete" BEFORE DELETE ON "SyncBooks"
BEGIN SELECT RAISE(ABORT, 'NO_DELETE:SyncBooks'); END;

CREATE TRIGGER "NumberBlock_no_delete" BEFORE DELETE ON "NumberBlock"
BEGIN SELECT RAISE(ABORT, 'NO_DELETE:NumberBlock'); END;

-- The capture switch, off.
INSERT INTO "SyncSession" ("id", "capturing", "applying") VALUES ('session', 0, 0);

-- ── 2. One log chain per laptop ─────────────────────────────────────────────────
-- AuditLog.chainSeq was UNIQUE on the column in 0001 (a constraint SQLite cannot drop),
-- and each laptop's chain counts from 1. So the table is rebuilt: every row copied
-- unchanged (chain null: the 1.0.0 chain), uniqueness now per chain. SequenceGap,
-- which references AuditLog, is rebuilt with it, its rows unchanged; its kind gains
-- LOST_DEVICE (a code, not a check). ChainHead_step accepts the heads "AuditLog:<id>".

DROP TRIGGER "Sequence_legal_step";

DROP TRIGGER "ChainHead_step";

CREATE TABLE "AuditLog__new" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "chainSeq" INTEGER NOT NULL,
  "occurredAt" TEXT NOT NULL,
  "localDate" TEXT NOT NULL CHECK ("localDate" IS NULL OR "localDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "localTime" TEXT NOT NULL CHECK ("localTime" IS NULL OR "localTime" GLOB '[0-2][0-9]:[0-5][0-9]'),
  "operation" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  "userId" TEXT,
  "userName" TEXT NOT NULL,
  "userRole" TEXT,
  "approvedByUserId" TEXT,
  "reason" TEXT NOT NULL,
  "ownerCode" TEXT NOT NULL,
  "entity" TEXT,
  "entityId" TEXT,
  "entityLabel" TEXT,
  "subjectKind" TEXT,
  "subjectId" TEXT,
  "subjectLabel" TEXT,
  "disclosure" TEXT,
  "recipient" TEXT,
  "changes" TEXT,
  "context" TEXT,
  "hashV" INTEGER NOT NULL,
  "prevHash" TEXT NOT NULL,
  "hash" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "chain" TEXT,
  FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("approvedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  CHECK ("operation" IN ('COLLECT','CONSULT','CHANGE','DISCLOSE','ERASE','SECURITY')),
  CHECK ("chain" IS NULL OR "chain" GLOB 'AuditLog:?*')
) STRICT;

INSERT INTO "AuditLog__new" ("id", "chainSeq", "occurredAt", "localDate", "localTime", "operation", "action", "userId", "userName", "userRole", "approvedByUserId", "reason", "ownerCode", "entity", "entityId", "entityLabel", "subjectKind", "subjectId", "subjectLabel", "disclosure", "recipient", "changes", "context", "hashV", "prevHash", "hash", "createdAt")
  SELECT "id", "chainSeq", "occurredAt", "localDate", "localTime", "operation", "action", "userId", "userName", "userRole", "approvedByUserId", "reason", "ownerCode", "entity", "entityId", "entityLabel", "subjectKind", "subjectId", "subjectLabel", "disclosure", "recipient", "changes", "context", "hashV", "prevHash", "hash", "createdAt" FROM "AuditLog";

CREATE TABLE "SequenceGap__new" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "key" TEXT NOT NULL,
  "year" INTEGER NOT NULL,
  "kind" TEXT NOT NULL,
  "fromValue" INTEGER NOT NULL,
  "toValue" INTEGER NOT NULL,
  "reason" TEXT NOT NULL,
  "auditLogId" TEXT,
  "createdAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  FOREIGN KEY ("auditLogId") REFERENCES "AuditLog__new" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT
) STRICT;

INSERT INTO "SequenceGap__new" ("id", "key", "year", "kind", "fromValue", "toValue", "reason", "auditLogId", "createdAt", "createdByUserId")
  SELECT "id", "key", "year", "kind", "fromValue", "toValue", "reason", "auditLogId", "createdAt", "createdByUserId" FROM "SequenceGap";

DROP TABLE "SequenceGap";

DROP TABLE "AuditLog";

ALTER TABLE "AuditLog__new" RENAME TO "AuditLog";

ALTER TABLE "SequenceGap__new" RENAME TO "SequenceGap";

CREATE INDEX "AuditLog_localDate_idx" ON "AuditLog" ("localDate");

CREATE INDEX "AuditLog_entity_entityId_idx" ON "AuditLog" ("entity", "entityId");

CREATE INDEX "AuditLog_subjectKind_subjectId_idx" ON "AuditLog" ("subjectKind", "subjectId");

CREATE INDEX "AuditLog_userId_localDate_idx" ON "AuditLog" ("userId", "localDate");

CREATE INDEX "AuditLog_operation_localDate_idx" ON "AuditLog" ("operation", "localDate");

CREATE UNIQUE INDEX "AuditLog_chain_seq" ON "AuditLog" (COALESCE("chain", 'AuditLog'), "chainSeq");

CREATE INDEX "SequenceGap_key_year_idx" ON "SequenceGap" ("key", "year");

CREATE TRIGGER "AuditLog_no_update" BEFORE UPDATE ON "AuditLog"
BEGIN SELECT RAISE(ABORT, 'APPEND_ONLY:AuditLog:update'); END;

CREATE TRIGGER "AuditLog_no_delete" BEFORE DELETE ON "AuditLog"
BEGIN SELECT RAISE(ABORT, 'APPEND_ONLY:AuditLog:delete'); END;

CREATE TRIGGER "AuditLog_chain_insert" BEFORE INSERT ON "AuditLog"
WHEN NEW."chainSeq" IS NOT (SELECT "lastSeq" + 1 FROM "ChainHead" WHERE "id" = COALESCE(NEW."chain", 'AuditLog'))
  OR NEW."prevHash" IS NOT (SELECT "lastHash" FROM "ChainHead" WHERE "id" = COALESCE(NEW."chain", 'AuditLog'))
  OR length(NEW."hash") <> 64
BEGIN SELECT RAISE(ABORT, 'CHAIN:AuditLog:out_of_sequence'); END;

CREATE TRIGGER "AuditLog_chain_advance" AFTER INSERT ON "AuditLog"
BEGIN UPDATE "ChainHead" SET "lastSeq" = NEW."chainSeq", "lastHash" = NEW."hash", "updatedAt" = NEW."createdAt" WHERE "id" = COALESCE(NEW."chain", 'AuditLog'); END;

CREATE TRIGGER "SequenceGap_no_update" BEFORE UPDATE ON "SequenceGap"
BEGIN SELECT RAISE(ABORT, 'APPEND_ONLY:SequenceGap:update'); END;

CREATE TRIGGER "SequenceGap_no_delete" BEFORE DELETE ON "SequenceGap"
BEGIN SELECT RAISE(ABORT, 'APPEND_ONLY:SequenceGap:delete'); END;

CREATE TRIGGER "Sequence_legal_step" BEFORE UPDATE ON "Sequence"
WHEN OLD."key" IN ('INVOICE', 'RECEIPT') AND NOT (
      (OLD."key" = 'INVOICE' AND NEW."lastValue" = OLD."lastValue" + 1 AND EXISTS (
         SELECT 1 FROM "Invoice" d WHERE d."numberYear" = OLD."year" AND d."numberSeq" = NEW."lastValue" AND d."issueDate" = NEW."lastDate"))
   OR (OLD."key" = 'RECEIPT' AND NEW."lastValue" = OLD."lastValue" + 1 AND EXISTS (
         SELECT 1 FROM "Receipt" d WHERE d."numberYear" = OLD."year" AND d."numberSeq" = NEW."lastValue" AND d."issueDate" = NEW."lastDate"))
   OR EXISTS (
         SELECT 1 FROM "SequenceGap" g WHERE g."key" = OLD."key" AND g."year" = OLD."year"
            AND g."fromValue" = OLD."lastValue" + 1 AND g."toValue" = NEW."lastValue"))
BEGIN SELECT RAISE(ABORT, 'SEQUENCE:legal_step'); END;

CREATE TRIGGER "ChainHead_step" BEFORE UPDATE ON "ChainHead"
WHEN NEW."id" IS NOT OLD."id" OR NEW."lastSeq" IS NOT OLD."lastSeq" + 1 OR length(NEW."lastHash") <> 64
  OR NOT EXISTS (
       SELECT 1 FROM "AuditLog" WHERE COALESCE("chain", 'AuditLog') = NEW."id" AND "chainSeq" = NEW."lastSeq" AND "hash" = NEW."lastHash"
       UNION ALL SELECT 1 FROM "Invoice" WHERE NEW."id" = 'Invoice' AND "chainSeq" = NEW."lastSeq" AND "hash" = NEW."lastHash"
       UNION ALL SELECT 1 FROM "InvoiceLine" WHERE NEW."id" = 'InvoiceLine' AND "chainSeq" = NEW."lastSeq" AND "hash" = NEW."lastHash"
       UNION ALL SELECT 1 FROM "InvoiceVisit" WHERE NEW."id" = 'InvoiceVisit' AND "chainSeq" = NEW."lastSeq" AND "hash" = NEW."lastHash"
       UNION ALL SELECT 1 FROM "Payment" WHERE NEW."id" = 'Payment' AND "chainSeq" = NEW."lastSeq" AND "hash" = NEW."lastHash"
       UNION ALL SELECT 1 FROM "PaymentAllocation" WHERE NEW."id" = 'PaymentAllocation' AND "chainSeq" = NEW."lastSeq" AND "hash" = NEW."lastHash"
       UNION ALL SELECT 1 FROM "Receipt" WHERE NEW."id" = 'Receipt' AND "chainSeq" = NEW."lastSeq" AND "hash" = NEW."lastHash"
       UNION ALL SELECT 1 FROM "LegalEvent" WHERE NEW."id" = 'LegalEvent' AND "chainSeq" = NEW."lastSeq" AND "hash" = NEW."lastHash")
BEGIN SELECT RAISE(ABORT, 'CHAIN:ChainHead:step'); END;

-- ── 3. Capture: 263 triggers on the 109 shared tables ──────────────────────
-- Every insert, change and delete is copied into SyncOutbox while capturing = 1 and
-- applying = 0; a write whose transaction was not stamped is refused (SYNC_UNSTAMPED).
-- Not captured: the @local tables (Sequence, ChainHead, BackupRun, the six sync tables),
-- the settings system.* and backup.*, and a change of only the @local columns
-- (PaymentDue.paidAmount, StockItem.onHandQty, User.failedSignInCount, User.lastSignInAt).

CREATE TRIGGER "Branch_sync_insert" AFTER INSERT ON "Branch"
WHEN (SELECT "capturing" = 1 AND "applying" = 0 FROM "SyncSession" WHERE "id" = 'session')
BEGIN
SELECT RAISE(ABORT, 'SYNC_UNSTAMPED') WHERE (SELECT "txId" FROM "SyncSession" WHERE "id" = 'session') IS NULL;
INSERT INTO "SyncOutbox" ("txId", "hlc", "tbl", "rowId", "op", "data")
  SELECT "txId", "hlc", 'Branch', NEW."id", 'I', json_object('id', NEW."id", 'code', NEW."code", 'name', NEW."name", 'address', NEW."address", 'phone', NEW."phone", 'city', NEW."city", 'isDefault', NEW."isDefault", 'isActive', NEW."isActive", 'createdAt', NEW."createdAt", 'updatedAt', NEW."updatedAt", 'createdByUserId', NEW."createdByUserId", 'updatedByUserId', NEW."updatedByUserId") FROM "SyncSession" WHERE "id" = 'session';
END;

CREATE TRIGGER "Branch_sync_update" AFTER UPDATE ON "Branch"
WHEN (SELECT "capturing" = 1 AND "applying" = 0 FROM "SyncSession" WHERE "id" = 'session')
  AND (NEW."id" IS NOT OLD."id"
    OR NEW."code" IS NOT OLD."code"
    OR NEW."name" IS NOT OLD."name"
    OR NEW."address" IS NOT OLD."address"
    OR NEW."phone" IS NOT OLD."phone"
    OR NEW."city" IS NOT OLD."city"
    OR NEW."isDefault" IS NOT OLD."isDefault"
    OR NEW."isActive" IS NOT OLD."isActive"
    OR NEW."createdAt" IS NOT OLD."createdAt"
    OR NEW."updatedAt" IS NOT OLD."updatedAt"
    OR NEW."createdByUserId" IS NOT OLD."createdByUserId"
    OR NEW."updatedByUserId" IS NOT OLD."updatedByUserId")
BEGIN
SELECT RAISE(ABORT, 'SYNC_UNSTAMPED') WHERE (SELECT "txId" FROM "SyncSession" WHERE "id" = 'session') IS NULL;
INSERT INTO "SyncOutbox" ("txId", "hlc", "tbl", "rowId", "op", "data")
  SELECT "txId", "hlc", 'Branch', NEW."id", 'U', (SELECT json_group_object("k", json("v")) FROM (
    SELECT 'id' AS "k", json_array(NEW."id", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'id')) AS "v" WHERE NEW."id" IS NOT OLD."id"
    UNION ALL SELECT 'code', json_array(NEW."code", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'code')) WHERE NEW."code" IS NOT OLD."code"
    UNION ALL SELECT 'name', json_array(NEW."name", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'name')) WHERE NEW."name" IS NOT OLD."name"
    UNION ALL SELECT 'address', json_array(NEW."address", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'address')) WHERE NEW."address" IS NOT OLD."address"
    UNION ALL SELECT 'phone', json_array(NEW."phone", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'phone')) WHERE NEW."phone" IS NOT OLD."phone"
    UNION ALL SELECT 'city', json_array(NEW."city", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'city')) WHERE NEW."city" IS NOT OLD."city"
    UNION ALL SELECT 'isDefault', json_array(NEW."isDefault", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'isDefault')) WHERE NEW."isDefault" IS NOT OLD."isDefault"
    UNION ALL SELECT 'isActive', json_array(NEW."isActive", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'isActive')) WHERE NEW."isActive" IS NOT OLD."isActive"
    UNION ALL SELECT 'createdAt', json_array(NEW."createdAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'createdAt')) WHERE NEW."createdAt" IS NOT OLD."createdAt"
    UNION ALL SELECT 'updatedAt', json_array(NEW."updatedAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'updatedAt')) WHERE NEW."updatedAt" IS NOT OLD."updatedAt"
    UNION ALL SELECT 'createdByUserId', json_array(NEW."createdByUserId", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'createdByUserId')) WHERE NEW."createdByUserId" IS NOT OLD."createdByUserId"
    UNION ALL SELECT 'updatedByUserId', json_array(NEW."updatedByUserId", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'Branch' AND "rowId" = NEW."id" AND "col" = 'updatedByUserId')) WHERE NEW."updatedByUserId" IS NOT OLD."updatedByUserId")) FROM "SyncSession" WHERE "id" = 'session';
INSERT INTO "SyncCell" ("tbl", "rowId", "col", "hlc")
  SELECT 'Branch', NEW."id", "k", (SELECT "hlc" FROM "SyncSession" WHERE "id" = 'session') FROM (
    SELECT 'id' AS "k" WHERE NEW."id" IS NOT OLD."id"
    UNION ALL SELECT 'code' WHERE NEW."code" IS NOT OLD."code"
    UNION ALL SELECT 'name' WHERE NEW."name" IS NOT OLD."name"
    UNION ALL SELECT 'address' WHERE NEW."address" IS NOT OLD."address"
    UNION ALL SELECT 'phone' WHERE NEW."phone" IS NOT OLD."phone"
    UNION ALL SELECT 'city' WHERE NEW."city" IS NOT OLD."city"
    UNION ALL SELECT 'isDefault' WHERE NEW."isDefault" IS NOT OLD."isDefault"
    UNION ALL SELECT 'isActive' WHERE NEW."isActive" IS NOT OLD."isActive"
    UNION ALL SELECT 'createdAt' WHERE NEW."createdAt" IS NOT OLD."createdAt"
    UNION ALL SELECT 'updatedAt' WHERE NEW."updatedAt" IS NOT OLD."updatedAt"
    UNION ALL SELECT 'createdByUserId' WHERE NEW."createdByUserId" IS NOT OLD."createdByUserId"
    UNION ALL SELECT 'updatedByUserId' WHERE NEW."updatedByUserId" IS NOT OLD."updatedByUserId")
  WHERE true
  ON CONFLICT ("tbl", "rowId", "col") DO UPDATE SET "hlc" = excluded."hlc";
END;

