CREATE TRIGGER "FileDescription_sync_insert" AFTER INSERT ON "FileDescription"
WHEN (SELECT "capturing" = 1 AND "applying" = 0 FROM "SyncSession" WHERE "id" = 'session')
BEGIN
SELECT RAISE(ABORT, 'SYNC_UNSTAMPED') WHERE (SELECT "txId" FROM "SyncSession" WHERE "id" = 'session') IS NULL;
INSERT INTO "SyncOutbox" ("txId", "hlc", "tbl", "rowId", "op", "data")
  SELECT "txId", "hlc", 'FileDescription', NEW."id", 'I', json_object('id', NEW."id", 'fileId', NEW."fileId", 'family', NEW."family", 'buildArea', NEW."buildArea", 'floors', NEW."floors", 'kitchens', NEW."kitchens", 'windows', NEW."windows", 'floorType', NEW."floorType", 'entrances', NEW."entrances", 'rooms', NEW."rooms", 'majlis', NEW."majlis", 'salons', NEW."salons", 'bathrooms', NEW."bathrooms", 'balconies', NEW."balconies", 'gardenArea', NEW."gardenArea", 'courtyardArea', NEW."courtyardArea", 'buildings', NEW."buildings", 'offices', NEW."offices", 'halls', NEW."halls", 'stores', NEW."stores", 'toilets', NEW."toilets", 'doors', NEW."doors", 'floorArea', NEW."floorArea", 'carParks', NEW."carParks", 'exits', NEW."exits", 'extraLabel', NEW."extraLabel", 'extraValue', NEW."extraValue", 'occupiedApartments', NEW."occupiedApartments", 'unoccupiedApartments', NEW."unoccupiedApartments", 'approxResidents', NEW."approxResidents", 'totalApartments', NEW."totalApartments", 'residentTurnover', NEW."residentTurnover", 'stairs', NEW."stairs", 'apartments', NEW."apartments", 'corridors', NEW."corridors", 'lifts', NEW."lifts", 'hasBasements', NEW."hasBasements", 'hasGreenSpaces', NEW."hasGreenSpaces", 'hasGarages', NEW."hasGarages", 'hasSharedRoofs', NEW."hasSharedRoofs", 'createdAt', NEW."createdAt", 'updatedAt', NEW."updatedAt") FROM "SyncSession" WHERE "id" = 'session';
END;

CREATE TRIGGER "FileDescription_sync_update" AFTER UPDATE ON "FileDescription"
WHEN (SELECT "capturing" = 1 AND "applying" = 0 FROM "SyncSession" WHERE "id" = 'session')
  AND (NEW."id" IS NOT OLD."id"
    OR NEW."fileId" IS NOT OLD."fileId"
    OR NEW."family" IS NOT OLD."family"
    OR NEW."buildArea" IS NOT OLD."buildArea"
    OR NEW."floors" IS NOT OLD."floors"
