INSERT INTO "SyncOutbox" ("txId", "hlc", "tbl", "rowId", "op", "data")
  SELECT "txId", "hlc", 'FileDescription', NEW."id", 'U', (SELECT json_group_object("k", json("v")) FROM (
    SELECT 'id' AS "k", json_array(NEW."id", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'id')) AS "v" WHERE NEW."id" IS NOT OLD."id"
