    UNION ALL SELECT 'floors', json_array(NEW."floors", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'floors')) WHERE NEW."floors" IS NOT OLD."floors"
