    UNION ALL SELECT 'floorType', json_array(NEW."floorType", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'floorType')) WHERE NEW."floorType" IS NOT OLD."floorType"
    UNION ALL SELECT 'entrances', json_array(NEW."entrances", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'entrances')) WHERE NEW."entrances" IS NOT OLD."entrances"
    UNION ALL SELECT 'rooms', json_array(NEW."rooms", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'rooms')) WHERE NEW."rooms" IS NOT OLD."rooms"
    UNION ALL SELECT 'majlis', json_array(NEW."majlis", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'majlis')) WHERE NEW."majlis" IS NOT OLD."majlis"
    UNION ALL SELECT 'salons', json_array(NEW."salons", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'salons')) WHERE NEW."salons" IS NOT OLD."salons"
