    UNION ALL SELECT 'gardenArea', json_array(NEW."gardenArea", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'gardenArea')) WHERE NEW."gardenArea" IS NOT OLD."gardenArea"
    UNION ALL SELECT 'courtyardArea', json_array(NEW."courtyardArea", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'courtyardArea')) WHERE NEW."courtyardArea" IS NOT OLD."courtyardArea"
    UNION ALL SELECT 'buildings', json_array(NEW."buildings", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'buildings')) WHERE NEW."buildings" IS NOT OLD."buildings"
    UNION ALL SELECT 'offices', json_array(NEW."offices", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'offices')) WHERE NEW."offices" IS NOT OLD."offices"
