    UNION ALL SELECT 'extraValue', json_array(NEW."extraValue", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'extraValue')) WHERE NEW."extraValue" IS NOT OLD."extraValue"
    UNION ALL SELECT 'occupiedApartments', json_array(NEW."occupiedApartments", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'occupiedApartments')) WHERE NEW."occupiedApartments" IS NOT OLD."occupiedApartments"
    UNION ALL SELECT 'unoccupiedApartments', json_array(NEW."unoccupiedApartments", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'unoccupiedApartments')) WHERE NEW."unoccupiedApartments" IS NOT OLD."unoccupiedApartments"
    UNION ALL SELECT 'approxResidents', json_array(NEW."approxResidents", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'approxResidents')) WHERE NEW."approxResidents" IS NOT OLD."approxResidents"
    UNION ALL SELECT 'totalApartments', json_array(NEW."totalApartments", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'totalApartments')) WHERE NEW."totalApartments" IS NOT OLD."totalApartments"
