    UNION ALL SELECT 'lifts', json_array(NEW."lifts", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'lifts')) WHERE NEW."lifts" IS NOT OLD."lifts"
    UNION ALL SELECT 'hasBasements', json_array(NEW."hasBasements", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'hasBasements')) WHERE NEW."hasBasements" IS NOT OLD."hasBasements"
    UNION ALL SELECT 'hasGreenSpaces', json_array(NEW."hasGreenSpaces", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'hasGreenSpaces')) WHERE NEW."hasGreenSpaces" IS NOT OLD."hasGreenSpaces"
    UNION ALL SELECT 'hasGarages', json_array(NEW."hasGarages", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'hasGarages')) WHERE NEW."hasGarages" IS NOT OLD."hasGarages"
    UNION ALL SELECT 'hasSharedRoofs', json_array(NEW."hasSharedRoofs", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'hasSharedRoofs')) WHERE NEW."hasSharedRoofs" IS NOT OLD."hasSharedRoofs"
    UNION ALL SELECT 'createdAt', json_array(NEW."createdAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'createdAt')) WHERE NEW."createdAt" IS NOT OLD."createdAt"
    UNION ALL SELECT 'updatedAt', json_array(NEW."updatedAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'FileDescription' AND "rowId" = NEW."id" AND "col" = 'updatedAt')) WHERE NEW."updatedAt" IS NOT OLD."updatedAt")) FROM "SyncSession" WHERE "id" = 'session';
INSERT INTO "SyncCell" ("tbl", "rowId", "col", "hlc")
  SELECT 'FileDescription', NEW."id", "k", (SELECT "hlc" FROM "SyncSession" WHERE "id" = 'session') FROM (
    SELECT 'id' AS "k" WHERE NEW."id" IS NOT OLD."id"
