INSERT INTO "SyncOutbox" ("txId", "hlc", "tbl", "rowId", "op", "data")
  SELECT "txId", "hlc", 'CostStudy', NEW."id", 'I', json_object('id', NEW."id", 'fileId', NEW."fileId", 'workers', NEW."workers", 'perVisitMin', NEW."perVisitMin", 'visitsPerWeek', NEW."visitsPerWeek", 'weeks', NEW."weeks", 'hourlyRate', NEW."hourlyRate", 'lines', NEW."lines", 'totalCost', NEW."totalCost", 'marginPercent', NEW."marginPercent", 'profitValue', NEW."profitValue", 'priceBeforeDiscount', NEW."priceBeforeDiscount", 'discount', NEW."discount", 'finalPrice', NEW."finalPrice", 'pricePerVisit', NEW."pricePerVisit", 'pricePerWeek', NEW."pricePerWeek", 'pricePerMonth', NEW."pricePerMonth", 'preparedByUserId', NEW."preparedByUserId", 'preparedAt', NEW."preparedAt", 'createdAt', NEW."createdAt", 'updatedAt', NEW."updatedAt", 'createdByUserId', NEW."createdByUserId", 'updatedByUserId', NEW."updatedByUserId") FROM "SyncSession" WHERE "id" = 'session';
