CREATE TRIGGER "CostStudy_sync_update" AFTER UPDATE ON "CostStudy"
WHEN (SELECT "capturing" = 1 AND "applying" = 0 FROM "SyncSession" WHERE "id" = 'session')
  AND (NEW."id" IS NOT OLD."id"
    OR NEW."fileId" IS NOT OLD."fileId"
    OR NEW."workers" IS NOT OLD."workers"
    OR NEW."perVisitMin" IS NOT OLD."perVisitMin"
    OR NEW."visitsPerWeek" IS NOT OLD."visitsPerWeek"
    OR NEW."weeks" IS NOT OLD."weeks"
    OR NEW."hourlyRate" IS NOT OLD."hourlyRate"
    OR NEW."lines" IS NOT OLD."lines"
    OR NEW."totalCost" IS NOT OLD."totalCost"
    OR NEW."marginPercent" IS NOT OLD."marginPercent"
    OR NEW."profitValue" IS NOT OLD."profitValue"
    OR NEW."priceBeforeDiscount" IS NOT OLD."priceBeforeDiscount"
    OR NEW."discount" IS NOT OLD."discount"
    OR NEW."finalPrice" IS NOT OLD."finalPrice"
    OR NEW."pricePerVisit" IS NOT OLD."pricePerVisit"
    OR NEW."pricePerWeek" IS NOT OLD."pricePerWeek"
    OR NEW."pricePerMonth" IS NOT OLD."pricePerMonth"
    OR NEW."preparedByUserId" IS NOT OLD."preparedByUserId"
    OR NEW."preparedAt" IS NOT OLD."preparedAt"
    OR NEW."createdAt" IS NOT OLD."createdAt"
    OR NEW."updatedAt" IS NOT OLD."updatedAt"
    OR NEW."createdByUserId" IS NOT OLD."createdByUserId"
    OR NEW."updatedByUserId" IS NOT OLD."updatedByUserId")
BEGIN
SELECT RAISE(ABORT, 'SYNC_UNSTAMPED') WHERE (SELECT "txId" FROM "SyncSession" WHERE "id" = 'session') IS NULL;
INSERT INTO "SyncOutbox" ("txId", "hlc", "tbl", "rowId", "op", "data")
  SELECT "txId", "hlc", 'CostStudy', NEW."id", 'U', (SELECT json_group_object("k", json("v")) FROM (
    SELECT 'id' AS "k", json_array(NEW."id", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'id')) AS "v" WHERE NEW."id" IS NOT OLD."id"
    UNION ALL SELECT 'fileId', json_array(NEW."fileId", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'fileId')) WHERE NEW."fileId" IS NOT OLD."fileId"
    UNION ALL SELECT 'workers', json_array(NEW."workers", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'workers')) WHERE NEW."workers" IS NOT OLD."workers"
    UNION ALL SELECT 'perVisitMin', json_array(NEW."perVisitMin", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'perVisitMin')) WHERE NEW."perVisitMin" IS NOT OLD."perVisitMin"
    UNION ALL SELECT 'visitsPerWeek', json_array(NEW."visitsPerWeek", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'visitsPerWeek')) WHERE NEW."visitsPerWeek" IS NOT OLD."visitsPerWeek"
    UNION ALL SELECT 'weeks', json_array(NEW."weeks", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'weeks')) WHERE NEW."weeks" IS NOT OLD."weeks"
    UNION ALL SELECT 'hourlyRate', json_array(NEW."hourlyRate", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'hourlyRate')) WHERE NEW."hourlyRate" IS NOT OLD."hourlyRate"
    UNION ALL SELECT 'lines', json_array(NEW."lines", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'lines')) WHERE NEW."lines" IS NOT OLD."lines"
    UNION ALL SELECT 'totalCost', json_array(NEW."totalCost", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'totalCost')) WHERE NEW."totalCost" IS NOT OLD."totalCost"
    UNION ALL SELECT 'marginPercent', json_array(NEW."marginPercent", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'marginPercent')) WHERE NEW."marginPercent" IS NOT OLD."marginPercent"
    UNION ALL SELECT 'profitValue', json_array(NEW."profitValue", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'profitValue')) WHERE NEW."profitValue" IS NOT OLD."profitValue"
    UNION ALL SELECT 'priceBeforeDiscount', json_array(NEW."priceBeforeDiscount", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'priceBeforeDiscount')) WHERE NEW."priceBeforeDiscount" IS NOT OLD."priceBeforeDiscount"
    UNION ALL SELECT 'discount', json_array(NEW."discount", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'discount')) WHERE NEW."discount" IS NOT OLD."discount"
    UNION ALL SELECT 'finalPrice', json_array(NEW."finalPrice", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'finalPrice')) WHERE NEW."finalPrice" IS NOT OLD."finalPrice"
    UNION ALL SELECT 'pricePerVisit', json_array(NEW."pricePerVisit", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'pricePerVisit')) WHERE NEW."pricePerVisit" IS NOT OLD."pricePerVisit"
    UNION ALL SELECT 'pricePerWeek', json_array(NEW."pricePerWeek", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'pricePerWeek')) WHERE NEW."pricePerWeek" IS NOT OLD."pricePerWeek"
    UNION ALL SELECT 'pricePerMonth', json_array(NEW."pricePerMonth", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'pricePerMonth')) WHERE NEW."pricePerMonth" IS NOT OLD."pricePerMonth"
    UNION ALL SELECT 'preparedByUserId', json_array(NEW."preparedByUserId", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'preparedByUserId')) WHERE NEW."preparedByUserId" IS NOT OLD."preparedByUserId"
    UNION ALL SELECT 'preparedAt', json_array(NEW."preparedAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'preparedAt')) WHERE NEW."preparedAt" IS NOT OLD."preparedAt"
    UNION ALL SELECT 'createdAt', json_array(NEW."createdAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'createdAt')) WHERE NEW."createdAt" IS NOT OLD."createdAt"
    UNION ALL SELECT 'updatedAt', json_array(NEW."updatedAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'updatedAt')) WHERE NEW."updatedAt" IS NOT OLD."updatedAt"
    UNION ALL SELECT 'createdByUserId', json_array(NEW."createdByUserId", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'createdByUserId')) WHERE NEW."createdByUserId" IS NOT OLD."createdByUserId"
    UNION ALL SELECT 'updatedByUserId', json_array(NEW."updatedByUserId", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'CostStudy' AND "rowId" = NEW."id" AND "col" = 'updatedByUserId')) WHERE NEW."updatedByUserId" IS NOT OLD."updatedByUserId")) FROM "SyncSession" WHERE "id" = 'session';
INSERT INTO "SyncCell" ("tbl", "rowId", "col", "hlc")
  SELECT 'CostStudy', NEW."id", "k", (SELECT "hlc" FROM "SyncSession" WHERE "id" = 'session') FROM (
    SELECT 'id' AS "k" WHERE NEW."id" IS NOT OLD."id"
    UNION ALL SELECT 'fileId' WHERE NEW."fileId" IS NOT OLD."fileId"
    UNION ALL SELECT 'workers' WHERE NEW."workers" IS NOT OLD."workers"
    UNION ALL SELECT 'perVisitMin' WHERE NEW."perVisitMin" IS NOT OLD."perVisitMin"
    UNION ALL SELECT 'visitsPerWeek' WHERE NEW."visitsPerWeek" IS NOT OLD."visitsPerWeek"
    UNION ALL SELECT 'weeks' WHERE NEW."weeks" IS NOT OLD."weeks"
    UNION ALL SELECT 'hourlyRate' WHERE NEW."hourlyRate" IS NOT OLD."hourlyRate"
    UNION ALL SELECT 'lines' WHERE NEW."lines" IS NOT OLD."lines"
    UNION ALL SELECT 'totalCost' WHERE NEW."totalCost" IS NOT OLD."totalCost"
    UNION ALL SELECT 'marginPercent' WHERE NEW."marginPercent" IS NOT OLD."marginPercent"
    UNION ALL SELECT 'profitValue' WHERE NEW."profitValue" IS NOT OLD."profitValue"
    UNION ALL SELECT 'priceBeforeDiscount' WHERE NEW."priceBeforeDiscount" IS NOT OLD."priceBeforeDiscount"
    UNION ALL SELECT 'discount' WHERE NEW."discount" IS NOT OLD."discount"
    UNION ALL SELECT 'finalPrice' WHERE NEW."finalPrice" IS NOT OLD."finalPrice"
    UNION ALL SELECT 'pricePerVisit' WHERE NEW."pricePerVisit" IS NOT OLD."pricePerVisit"
    UNION ALL SELECT 'pricePerWeek' WHERE NEW."pricePerWeek" IS NOT OLD."pricePerWeek"
    UNION ALL SELECT 'pricePerMonth' WHERE NEW."pricePerMonth" IS NOT OLD."pricePerMonth"
    UNION ALL SELECT 'preparedByUserId' WHERE NEW."preparedByUserId" IS NOT OLD."preparedByUserId"
    UNION ALL SELECT 'preparedAt' WHERE NEW."preparedAt" IS NOT OLD."preparedAt"
    UNION ALL SELECT 'createdAt' WHERE NEW."createdAt" IS NOT OLD."createdAt"
    UNION ALL SELECT 'updatedAt' WHERE NEW."updatedAt" IS NOT OLD."updatedAt"
    UNION ALL SELECT 'createdByUserId' WHERE NEW."createdByUserId" IS NOT OLD."createdByUserId"
    UNION ALL SELECT 'updatedByUserId' WHERE NEW."updatedByUserId" IS NOT OLD."updatedByUserId")
  WHERE true
  ON CONFLICT ("tbl", "rowId", "col") DO UPDATE SET "hlc" = excluded."hlc";
END;

