    UNION ALL SELECT 'kind', json_array(NEW."kind", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'NumberBlock' AND "rowId" = NEW."id" AND "col" = 'kind')) WHERE NEW."kind" IS NOT OLD."kind"
    UNION ALL SELECT 'answer', json_array(NEW."answer", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'NumberBlock' AND "rowId" = NEW."id" AND "col" = 'answer')) WHERE NEW."answer" IS NOT OLD."answer"
    UNION ALL SELECT 'answeredAt', json_array(NEW."answeredAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'NumberBlock' AND "rowId" = NEW."id" AND "col" = 'answeredAt')) WHERE NEW."answeredAt" IS NOT OLD."answeredAt"
    UNION ALL SELECT 'used', json_array(NEW."used", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'NumberBlock' AND "rowId" = NEW."id" AND "col" = 'used')) WHERE NEW."used" IS NOT OLD."used"
    UNION ALL SELECT 'createdAt', json_array(NEW."createdAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'NumberBlock' AND "rowId" = NEW."id" AND "col" = 'createdAt')) WHERE NEW."createdAt" IS NOT OLD."createdAt"
    UNION ALL SELECT 'updatedAt', json_array(NEW."updatedAt", (SELECT "hlc" FROM "SyncCell" WHERE "tbl" = 'NumberBlock' AND "rowId" = NEW."id" AND "col" = 'updatedAt')) WHERE NEW."updatedAt" IS NOT OLD."updatedAt")) FROM "SyncSession" WHERE "id" = 'session';
INSERT INTO "SyncCell" ("tbl", "rowId", "col", "hlc")
  SELECT 'NumberBlock', NEW."id", "k", (SELECT "hlc" FROM "SyncSession" WHERE "id" = 'session') FROM (
    SELECT 'id' AS "k" WHERE NEW."id" IS NOT OLD."id"
    UNION ALL SELECT 'key' WHERE NEW."key" IS NOT OLD."key"
    UNION ALL SELECT 'year' WHERE NEW."year" IS NOT OLD."year"
    UNION ALL SELECT 'blockIndex' WHERE NEW."blockIndex" IS NOT OLD."blockIndex"
    UNION ALL SELECT 'size' WHERE NEW."size" IS NOT OLD."size"
    UNION ALL SELECT 'deviceId' WHERE NEW."deviceId" IS NOT OLD."deviceId"
    UNION ALL SELECT 'kind' WHERE NEW."kind" IS NOT OLD."kind"
    UNION ALL SELECT 'answer' WHERE NEW."answer" IS NOT OLD."answer"
    UNION ALL SELECT 'answeredAt' WHERE NEW."answeredAt" IS NOT OLD."answeredAt"
    UNION ALL SELECT 'used' WHERE NEW."used" IS NOT OLD."used"
    UNION ALL SELECT 'createdAt' WHERE NEW."createdAt" IS NOT OLD."createdAt"
    UNION ALL SELECT 'updatedAt' WHERE NEW."updatedAt" IS NOT OLD."updatedAt")
  WHERE true
  ON CONFLICT ("tbl", "rowId", "col") DO UPDATE SET "hlc" = excluded."hlc";
END;
